/**
  Terence Young (Dr. No, From Russia With Love, Thunderball)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
        UUID_TO_BIN('2d941726-5f84-4ab5-a5d0-1bd79b14fae4'),
        'Terence Young',
        'Stewart Terence Herbert Young was born on June 20, 1915, in Shanghai, China, where his father served as a police commissioner. His family eventually returned to England, where he attended the Harrow School before reading history at St Catharine''s College, Cambridge. During World War II, Young served as a tank commander in the Irish Guards and took part in Operation Market Garden at the Battle of Arnhem, where he was wounded in action. Coincidentally, while recovering, he was cared for by a young volunteer nurse named Audrey Kathleen Ruston, who would later become world-famous as Audrey Hepburn. Young would direct her two decades later in the acclaimed 1967 thriller Wait Until Dark. Young began his entertainment career as a screenwriter in the late 1930s before making his solo directorial debut with the 1948 drama Corridor of Mirrors. Over the 1950s, he built a reputation as a versatile craftsman of war films, melodramas, and action features, frequently collaborating with producers Albert R. Broccoli and Irving Allen. When Broccoli and co-producer Harry Saltzman set out to adapt Ian Fleming''s spy novels for the big screen, they selected Young to direct the first official 007 film, Dr. No (1962). Young was instrumental in shaping the cinematic version of James Bond. A sophisticated, impeccably dressed gentleman who was well-versed in fine dining, luxury tailors, and luxury wines, Young essentially molded actor Sean Connery in his own image. He took the young Scottish actor to his personal Savile Row tailor, taught him how to walk and talk with urbane grace, and showed him how to carry himself as a worldly secret agent. Young went on to direct two more landmark Bond pictures: From Russia with Love (1963) and Thunderball (1965), cementing the visual formula, dry humor, and grand scale of the franchise. His dedication to the craft became legendary during the shoot for From Russia with Love, when a helicopter carrying him crashed into the sea; after being pulled from the water, Young returned to set to continue filming within thirty minutes. Beyond his defining work on the Bond series, Young directed over thirty films across various genres, including international action features starring Charles Bronson (Red Sun, The Valachi Papers) and historical dramas like Mayerling. He remained an active filmmaker in Europe and Hollywood into the 1980s. Young passed away from a heart attack in Cannes, France, on September 7, 1994, at the age of 79.',
        'British',
        '1915-06-20',
        '1994-09-07',
        CURRENT_TIMESTAMP(6),
        CURRENT_TIMESTAMP(6)
);

/**
  Guy Hamilton (Goldfinger, Diamonds are forever, Live and let die, The man with the golden gun)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1a8eeb34-1968-47a9-876f-4e4f7810f508'),
       'Guy Hamilton',
       'Mervyn Guy Hamilton was born on September 16, 1922, in Paris, France, to British diplomatic parents. Growing up in France gave him a cosmopolitan upbringing and a fluent command of the language, which helped him secure his first film job at the Victorine Studios in Nice during the late 1930s. When World War II broke out, Hamilton returned to England and joined the Royal Navy, serving as an officer on motor torpedo boats and participating in covert missions to retrieve downed Allied airmen from occupied France. After the war, Hamilton entered the British film industry as an assistant director, working alongside legendary filmmakers such as Carol Reed on classics like The Third Man (1949). He made his solo directorial debut with the 1952 mystery drama The Ringer and steadily built a reputation for crisp, lighthearted storytelling and strong visual pacing through successful 1950s pictures like An Inspector Calls and the World War II POW escape drama The Colditz Story. When Terence Young stepped away from directing the third James Bond film, producers Albert R. Broccoli and Harry Saltzman recruited Hamilton to helm Goldfinger (1964). Hamilton transformed the franchise by introducing a faster pace, sharper humor, elaborate gadgets, and larger-than-life villains. Goldfinger became an immense cultural and commercial phenomenon, solidifying the classic 007 blockbuster formula. Hamilton`s success with Goldfinger led him to direct three additional Bond films: Diamonds Are Forever (1971), which marked Sean Connery''s final official Eon production, followed by Live and Let Die (1973) and The Man with the Golden Gun (1974), which successfully launched Roger Moore''s tenure as the spy. Beyond 007, Hamilton enjoyed a long and distinguished career directing notable British and international productions. Highlights include the epic World War II aviation movie Battle of Britain (1969), the Michael Caine spy thriller Funeral in Berlin (1966), and two popular Agatha Christie adaptations, The Mirror Crack''d (1980) and Evil Under the Sun (1982). Hamilton eventually retired to Mallorca, Spain, where he passed away on April 20, 2016, at the age of 93.',
       'British',
       '1922-09-16',
       '2016-04-20',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lewis Gilbert (You only live twice, The spy who loved me, Moonraker)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b0ea2235-7998-4674-8824-35b5250b9901'),
       'Lewis Gilbert',
       'Lewis Gilbert was born on March 6, 1920, in London, England, into a family of variety performers. He began his career in the entertainment industry as a child actor in silent films and on stage during the 1920s and 1930s. When World War II began, Gilbert joined the Royal Air Force Film Unit, where he gained invaluable hands-on experience directing wartime documentaries and instruction materials alongside prominent American filmmakers like Garson Kanin. Following the war, Gilbert transitioned to feature filmmaking in the late 1940s and established himself as one of Britain''s most reliable and versatile directors. Throughout the 1950s, he earned widespread acclaim for his gripping World War II dramas, including The Sea Shall Not Have Them, Reach for the Sky, and Sink the Bismarck!. His career reached new artistic heights in 1966 with the comedy-drama Alfie, starring Michael Caine, which won the Special Jury Prize at the Cannes Film Festival and earned five Academy Award nominations. Following the success of Alfie, producers Albert R. Broccoli and Harry Saltzman recruited Gilbert to helm the fifth James Bond movie, You Only Live Twice (1967). Gilbert brought a grand, widescreen cinematic sensibility to the franchise, overseeing massive sets like SPECTRE''s volcano lair designed by Ken Adam and expanding the scale of 007''s adventures to a global spectacle. Gilbert would later return to the Bond franchise twice more during the Roger Moore era, directing The Spy Who Loved Me (1977) and Moonraker (1979). Both films were huge box-office hits that leaned into lavish, sci-fi-infused spectacle, with The Spy Who Loved Me often cited as one of Moore''s finest outings. Beyond the Bond series, Gilbert enjoyed an exceptionally long and diverse career spanning over six decades. He proved equally adept at smaller, character-driven stories, directing two beloved British comedy-dramas adapted from Willy Russell plays: Educating Rita (1983) and Shirley Valentine (1989), both of which earned multiple Oscar nominations. Gilbert was appointed a Commander of the Order of the British Empire (CBE) in 1997 for his contributions to cinema. He passed away peacefully in his sleep at his home in Monaco on February 23, 2018, at the age of 97.',
       'British',
       '1920-03-06',
       '2018-02-23',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Peter Hunt (On her Majesty's secret service)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('81894653-2e54-4e01-b015-ef029e938d34'),
       'Peter Hunt',
       'Peter Roger Hunt was born on March 11, 1925, in London, England. During World War II, he served in the military before transitioning into the entertainment industry, starting out as an assistant cutter and assembling editor in the late 1940s and early 1950s. He built a reputation as a highly talented film editor throughout the 1950s, working on films such as The Admirable Crichton and Sink the Bismarck!  Hunt was one of the single most influential architects of the James Bond series. He served as the supervising editor for the first four Bond films—Dr. No (1962), From Russia with Love (1963), Goldfinger (1964), and Thunderball (1965)—where he pioneered a fast-paced, signature "crash cutting" editing style that defined the action aesthetic of the franchise. After serving as second unit director on You Only Live Twice (1967), producers Albert R. Broccoli and Harry Saltzman handed him the main directors chair for On Her Majesty''s Secret Service (1969). Directing George Lazenby in his sole outing as 007, Hunt aimed to make a more realistic, grounded adaptation that closely followed Ian Fleming''s original novel. His direction delivered dynamic action sequences and an emotional weight that made the film a distinctive high point in the series. Although Eon Productions invited him to direct future Bond features, Hunt chose to move on to other ventures. Beyond 007, he directed action-adventures and thrillers such as Gold (1974) and Shout at the Devil (1976), both starring Roger Moore, as well as the Charles Bronson action films Death Hunt (1981) and Assassination (1987). He also directed television, including episodes of The Persuaders! Hunt passed away from heart failure in Santa Monica, California, on August 14, 2002, at the age of 77.',
       'British',
       '1925-03-11',
       '2002-08-14',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Glen (For your eyes only, Octopussy, A view to a kill, The living daylights, License to kill)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('29e4e57a-000c-486f-9bf7-4ce84899df6c'),
       'John Glen',
       'John Glen was born on May 15, 1932, in Sunbury-on-Thames, England. His entry into cinema began in 1945 as a teenage messenger boy at Shepperton Studios, where he quickly worked his way up through the sound and editorial departments on classic British films, including Carol Reed''s The Third Man. After completing two years of compulsory service in the Royal Air Force, Glen established a thriving career as a film editor and second unit director, contributing to popular television series like Danger Man and The Avengers, as well as major action features such as Superman and The Wild Geese.  Glen became an essential creative force within the James Bond franchise during the 1960s and 1970s, serving as the editor and second unit director on On Her Majesty''s Secret Service, The Spy Who Loved Me, and Moonraker. His skill for staging visceral stunt work was highlighted when he directed iconic action sequences, including the legendary union-jack parachute ski jump that opened The Spy Who Loved Me.  Impressed by his knack for action storytelling and visual pacing, producer Albert R. "Cubby" Broccoli promoted Glen to full director for For Your Eyes Only (1981). Tasked with scaling back the sci-fi excess of Moonraker, Glen brought the franchise back to its grounded spy roots, emphasizing thrilling real-world stunt work, tension, and classic espionage.  His directorial debut was a massive critical and box-office success, launching a record-breaking streak. Glen went on to direct all five James Bond movies released throughout the 1980s: For Your Eyes Only, Octopussy (1983), A View to a Kill (1985), The Living Daylights (1987), and Licence to Kill (1989). Directing across both the Roger Moore and Timothy Dalton eras, Glen holds the record for directing the most Bond films of any filmmaker in history.  Following his ten-year reign over 007, Glen continued directing feature films and television projects, including Aces: Iron Eagle III, the historical drama Christopher Columbus: The Discovery, and the sci-fi series Space Precinct. In 2001, he published his autobiography, fittingly titled For My Eyes Only, reflecting on his distinguished career as one of Britain''s premier action and stunt directors.',
       'British',
       '1932-05-15',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Martin Campbell (Goldeneye, Casino Royale)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('04f63e27-2f0e-456d-bbac-a8148de87088'),
       'Martin Campbell',
       'Martin Campbell was born on October 24, 1943, in Hastings, New Zealand. Moving to London in 1966 to pursue a career in filmmaking, he gained early experience as a camera operator and producer before stepping into the director''s chair in the 1970s. He built a strong reputation in British television during the 1980s by directing high-profile projects, including the acclaimed thriller miniseries Edge of Darkness, which earned him widespread industry recognition and multiple BAFTA nominations. Campbell holds a unique and celebrated place in James Bond history as the director entrusted with reinventing 007 for two different eras. He first directed GoldenEye (1995), which successfully introduced Pierce Brosnan as Bond and modernized the franchise for a post-Cold War world. Over a decade later, he was brought back to helm Casino Royale (2006), introducing Daniel Craig and executing a gritty, realistic reboot that reshaped the contemporary action landscape. Both films were massive critical and financial successes, widely regarded as top-tier entries in the entire franchise. Beyond his groundbreaking work with James Bond, Campbell has established a prolific career directing major Hollywood blockbusters and suspense thrillers. His filmography includes The Mask of Zorro and its sequel The Legend of Zorro, the survival drama Vertical Limit, the sci-fi spectacle Green Lantern, and action thrillers like The Foreigner and Memory. Known for his sharp narrative pacing, grounded character moments, and masterclass handling of practical action choreography, Campbell remains one of modern cinema''s most respected action directors.',
       'New Zealand',
       '1943-10-24',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Roger Spottiswoode (Tomorrow Never Dies)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('39b37032-e49a-43a3-9973-94ee8e1bd6b3'),
       'Roger Spottiswoode',
       'Roger Spottiswoode was born on January 5, 1945, in Ottawa, Ontario, Canada, and raised in the United Kingdom. He entered the film industry during the late 1960s, working his way up through the editorial department on major British and international productions. He served as an editor on acclaimed films such as Sam Peckinpah''s Straw Dogs and Pat Garrett and Billy the Kid, experience that honed his sharp sense of narrative pacing and visual rhythm. Spottiswoode made his directorial debut in 1980 with the slasher thriller Terror Train, starring Jamie Lee Curtis. Throughout the 1980s and early 1990s, he built a versatile body of work across multiple genres, directing the political drama Under Fire, the buddy-cop comedy Turner & Hooch, the action-comedy Air America, and the critically acclaimed HBO docudrama And the Band Played On, which earned him an Emmy nomination for Outstanding Directing. In 1997, Spottiswoode was chosen to direct Tomorrow Never Dies, the 18th official entry in the 007 series and Pierce Brosnan''s second outing as James Bond. Facing tight production schedules and a rapidly changing film landscape, Spottiswoode delivered a high-octane action thriller centered on a power-hungry media mogul attempting to provoke a global conflict for broadcast ratings—a storyline that proved remarkably prescient regarding modern news media and information warfare. Following his contribution to the Bond franchise, Spottiswoode continued to direct a diverse slate of feature films and television projects. His post-Bond credits include the futuristic sci-fi thriller The 6th Day starring Arnold Schwarzenegger, the biographical drama Shake Hands with the Devil, and the hit family film A Street Cat Named Bob. Throughout his career, he has remained known for his adaptability, technical craft, and ability to weave engaging character dynamics into high-stakes storytelling.',
       'Canadian-British',
       '1945-01-15',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michael Apted (The world is not enough)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('31283991-54c6-4746-9fd5-bfa4c466fa55'),
       'Michael Apted',
       'Michael Apted was born on June 29, 1941, in Aylesbury, Buckinghamshire, England. He studied law and history at Downing College, Cambridge, before entering the television industry as a trainee researcher at Granada Television in 1963. There, he worked on the ground-breaking documentary project 7 Up, taking full directorial control of its subsequent installments. The acclaimed Up series tracked the lives of fourteen British individuals every seven years, running for over five decades and cementing Apted''s place as a master of intimate, long-term human storytelling. Alongside his celebrated documentary work, Apted transitioned smoothly into directing narrative feature films. He earned international recognition for his nuanced handling of character-driven dramas and biographical stories, helming acclaimed films such as Coal Miner''s Daughter, which received seven Academy Award nominations including Best Picture, as well as Gorillas in the Mist, Class Action, and Nell. Beyond his filmmaking, he also served as the President of the Directors Guild of America from 2003 to 2009. In 1999, Apted was selected to direct The World Is Not Enough, the 19th entry in the James Bond series and Pierce Brosnan''s third film as 007. Producer Barbara Broccoli chose Apted specifically to bring greater emotional depth, narrative weight, and strong female character dynamics to the action franchise. Apted delivered a high-stakes espionage thriller that balanced trademark spectacular stunt work—such as the iconic Thames boat chase—with a complex personal storyline between Bond, oil heiress Electra King, and nuclear physicist Christmas Jones. Following his Bond entry, Apted continued to direct across film, television, and documentary formats. His later credits include the historical drama Amazing Grace, the fantasy blockbuster The Chronicles of Narnia: The Voyage of the Dawn Treader, episodes of the HBO series Rome, and 63 Up in 2019. Apted passed away at his home in Los Angeles on January 7, 2021, at the age of 79, leaving behind a prolific legacy as one of Britain''s most versatile and insightful directors.',
       'British',
       '1941-02-10',
       '2021-01-07',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lee Tamahori (Die another day)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('dd4cad36-a151-4e7c-8257-3a460aee0067'),
       'Lee Tamahori',
       'Warren Lee Tamahori was born on April 22, 1950, in Wellington, New Zealand, of Māori descent on his father''s side and British on his mother''s. He began his artistic career as a commercial artist and photographer before joining the New Zealand film industry in the late 1970s, starting out as a boom operator and working his way up to assistant director. During the 1980s, he transitioned into directing television commercials, spending ten years establishing a reputation for high-impact visual storytelling. Tamahori made an explosive feature directorial debut with the gritty, hard-hitting drama Once Were Warriors in 1994. Depicting the harsh realities of an urban Māori family dealing with domestic violence and systemic hardship, the film became a massive international critical success and remains one of the most culturally significant films in New Zealand history. Its success immediately launched him into a high-profile Hollywood career. Following his debut, Tamahori directed a string of American thrillers, including the period neo-noir Mulholland Falls, the survival action drama The Edge starring Anthony Hopkins, and the suspense thriller Along Came a Spider starring Morgan Freeman. In 2002, he was chosen to helm Die Another Day, the 20th official James Bond feature and Pierce Brosnan''s fourth and final outing as 007. Tamahori brought a stylized, modern energy to the franchise, delivering a blockbuster filled with high-tech gadgetry, explosive action, CGI-heavy sequences, and major box-office numbers. After his landmark Bond entry, Tamahori continued directing large-scale action features and indie dramas, including xXx: State of the Union, the Nicolas Cage sci-fi thriller Next, and the biographical drama The Devil''s Double. In his later years, he returned home to New Zealand to direct stories rooted in indigenous culture and history, including Mahana and the colonial-era historical drama The Convert. Known throughout his career for his visual flair and versatile handling of both intimate drama and massive action, Tamahori passed away at home in New Zealand on November 7, 2025, at the age of 75. An engaging look at Lee Tamahori''s career and his passion for returning to New Zealand storytelling can be viewed in Lee Tamahori''s latest film on pre-colonial NZ, which provides context on his artistic journey from blockbuster films back to his roots.',
       'New Zealand',
       '1950-06-17',
       '2025-11-07',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Marc Forster (Quantum of solace)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('cfba2942-ac6d-405c-8a82-bccb2a2ef81a'),
       'Marc Forster',
       'Marc Forster was born on November 30, 1969, in Illertissen, West Germany, and raised in Switzerland. At the age of twenty, he moved to the United States to study film at New York University''s Tisch School of the Arts, graduating in 1993 and beginning his career in independent cinema. He achieved a major breakthrough with the intense psychological drama Monster''s Ball in 2001, which earned critical acclaim and saw Halle Berry win the Academy Award for Best Actress. Following this initial success, Forster established a reputation as an exceptionally versatile filmmaker capable of tackling a wide variety of genres. He went on to helm the acclaimed biographical drama Finding Neverland, which earned seven Academy Award nominations including Best Picture, as well as the surreal psychological thriller Stay, the whimsical existential comedy Stranger than Fiction, and the literary adaptation The Kite Runner. In 2008, Forster was selected to direct Quantum of Solace, the 22nd official film in the James Bond series and Daniel Craig''s second turn as 007. As a German-Swiss national, Forster became the first director from outside the British Commonwealth to direct an official Bond movie, as well as the youngest director in the history of the franchise at thirty-eight years old. He brought a visually stark, auteur-driven sensibility to the direct sequel to Casino Royale, structuring the film''s gritty action sequences around thematic motifs and guiding Bond through a raw narrative centered on grief and retribution. After his contribution to the Bond series, Forster continued to direct large-scale blockbusters and intimate character pieces. His post-Bond filmography includes the apocalyptic action thriller World War Z starring Brad Pitt, the Disney live-action fantasy drama Christopher Robin, and the comedy-drama A Man Called Otto starring Tom Hanks. Known for his eclectic choices and visually distinctive approach, Forster remains one of the most adaptable international directors working in modern cinema.',
       'German-Swiss',
       '1969-11-30',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Sam Mendes (Skyfall, Spectre)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('91992cf2-4368-4445-9555-25546ea6922b'),
       'Sam Mendes',
       'Samuel Alexander Mendes was born on August 1, 1965, in Reading, Berkshire, England. He developed a passion for the stage while attending Peterhouse, Cambridge, and quickly built a brilliant career as a theatre director. He gained widespread acclaim during his tenure as the artistic director of London''s Donmar Warehouse throughout the 1990s, where he staged celebrated revivals of classic plays and musicals. Mendes made a remarkable transition into feature filmmaking with his directorial screen debut, American Beauty, in 1999. The film became a massive critical and commercial success, earning five Academy Awards, including Best Picture and Best Director for Mendes. Following his Oscar-winning debut, Mendes established himself as a premier filmmaker known for exquisite visual compositions, compelling character dynamics, and masterclass staging. He directed several critically acclaimed projects over the next decade, including the 1930s crime drama Road to Perdition, the Gulf War drama Jarhead, the intense marital drama Revolutionary Road, and the indie comedy-drama Away We Go. Throughout this period, he maintained a distinguished career in theatre, directing major productions on both the West End and Broadway. In 2012, Mendes was chosen to direct Skyfall, the 23rd entry in the James Bond series and Daniel Craig''s third outing as 007. Arriving during the 50th anniversary of the franchise, Skyfall achieved extraordinary success, receiving universal critical acclaim and becoming the highest-grossing James Bond film of all time with over one billion dollars worldwide. Mendes brought an elevated artistic sensibility, deep thematic exploration, and stunning cinematography to the film. His work was so highly regarded by producers Barbara Broccoli and Michael G. Wilson that he was persuaded to return to helm the 2015 follow-up, Spectre, making him the first director to handle back-to-back Bond films since John Glen in the 1980s. After completing his two-film tenure with the Bond franchise, Mendes returned to scale cinematic storytelling. He co-wrote and directed the gripping World War I epic 1917 in 2019, which earned him two Golden Globe Awards and three Academy Award nominations, while pioneering a seamless single-shot narrative technique. He followed this with the reflective romantic drama Empire of Light in 2022. Mendes continues to be recognized as one of the most distinguished and accomplished British directors of both stage and screen, knighted for his services to drama in the 2020 New Year Honours.',
       'British',
       '1965-08-01',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Cary Joji Fukunaga (No time to die)
 */
INSERT INTO directors (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3e68940b-4aad-4912-a03f-14a07929f6e3'),
       'Cary Joji Fukunaga',
       'Cary Joji Fukunaga was born on July 10, 1977, in Oakland, California, to a Japanese-American father and a mother of Swedish descent. After earning a degree in history from the University of California, Santa Cruz, he pursued filmmaking at New York University''s Tisch School of the Arts. Fukunaga burst onto the international film scene with his 2009 feature directorial debut Sin Nombre, a gritty Spanish-language drama about Central American migrants traveling atop trains toward the United States, which won him the Directing Award at the Sundance Film Festival. He quickly established a reputation for striking visual composition and narrative realism, following his debut with a lauded 2011 adaptation of Charlotte Brontë''s Jane Eyre starring Mia Wasikowska and Michael Fassbender. Fukunaga achieved massive critical and cultural acclaim in 2014 when he directed and executive produced the entire first season of HBO''s anthology series True Detective. His direction, marked by atmospheric dread and a famous six-minute continuous tracking shot, earned him the Primetime Emmy Award for Outstanding Directing for a Drama Series. He followed this success by writing, directing, and serving as cinematographer for the 2015 African child-soldier drama Beasts of No Nation starring Idris Elba. Moving fluidly between television and feature film projects, he subsequently co-wrote the blockbuster horror adaptation It in 2017 and directed the surreal Netflix limited series Maniac in 2018. In September 2018, Fukunaga was selected to helm No Time to Die, taking over the project after director Danny Boyle departed. He made history by becoming the first American filmmaker to direct an official James Bond feature in the franchise''s long history. Fukunaga also co-wrote the screenplay alongside Neal Purvis, Robert Wade, and Phoebe Waller-Bridge. Released in 2021 after global delays, the film served as the emotional, high-stakes finale to Daniel Craig''s five-film tenure as 007, earning widespread praise for its scale, cinematography, and bold dramatic closure. Following his Bond entry, Fukunaga continued his work across film and high-budget television, directing episodes and executive producing the World War II miniseries Masters of the Air for Apple TV+. Known for his technical precision, hands-on visual style, and ability to handle both intimate character studies and massive action spectacles, he remains a prominent force in contemporary international cinema.',
       'American',
       '1977-07-10',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);